code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3 for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r,c))
    # The 2 rails through the symbol center determine the direction of projection.
    vertical = sum(1 for r in range(h) for c in range(w) if grid[r][c] == 2 and all(grid[rr][c] == 2 for rr in range(h)))
    horizontal = sum(1 for r in range(h) for c in range(w) if grid[r][c] == 2 and all(grid[r][cc] == 2 for cc in range(w)))
    # ARC rails can have interruptions where a symbol sits; infer orientation by runs of 2s.
    vscore = sum(sum(1 for r in range(h) if grid[r][c] == 2) for c in range(w))
    hscore = sum(sum(1 for c in range(w) if grid[r][c] == 2) for r in range(h))
    project_horizontally = vscore >= hscore
    object_centers = set(centers)
    for r, c in centers:
        if project_horizontally:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            crossings = [(r, cc) for cc in range(w) if grid[r][cc] == 2]
        else:
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            crossings = [(rr, c) for rr in range(h) if grid[rr][c] == 2]
        for cr, cc in crossings:
            if (cr, cc) in object_centers:
                continue
            for rr in range(cr-1, cr+2):
                for ccc in range(cc-1, cc+2):
                    if 0 <= rr < h and 0 <= ccc < w and (rr, ccc) != (cr,cc):
                        out[rr][ccc] = 1
    return out
'''
